{"question_id": 28, "sql": "SELECT sch.School, sch.DOC FROM schools sch JOIN frpm f ON sch.CDSCode = f.CDSCode WHERE sch.FundingType = 'Locally funded' AND (f.`Enrollment (K-12)` - f.`Enrollment (Ages 5-17)`) > (SELECT AVG(f2.`Enrollment (K-12)` - f2.`Enrollment (Ages 5-17)`) FROM schools sch2 JOIN frpm f2 ON sch2.CDSCode = f2.CDSCode WHERE sch2.FundingType = 'Locally funded')"}
{"question_id": 36, "sql": "SELECT sch.AdmFName1, sch.AdmLName1, sch.AdmFName2, sch.AdmLName2, sch.AdmFName3, sch.AdmLName3 FROM satscores s JOIN schools sch ON s.cds = sch.CDSCode ORDER BY s.NumGE1500 DESC LIMIT 1"}
{"question_id": 62, "sql": "SELECT COUNT(*) FROM schools sch JOIN frpm f ON sch.CDSCode = f.CDSCode WHERE sch.County = 'Los Angeles' AND sch.Charter = 0 AND f.`Free Meal Count (K-12)` * 100.0 / f.`Enrollment (K-12)` < 0.18"}
{"question_id": 83, "sql": "SELECT sch.City, COUNT(*) FROM schools sch JOIN frpm f ON sch.CDSCode = f.CDSCode WHERE sch.Magnet = 1 AND sch.GSserved = 'K-8' AND f.`NSLP Provision Status` = 'Multiple Provision Types' GROUP BY sch.City"}
{"question_id": 87, "sql": "SELECT AdmEmail1, AdmEmail2 FROM schools WHERE County = 'San Bernardino' AND City = 'San Bernardino' AND DOC = '54' AND SOC = '62' AND OpenDate BETWEEN '2009-01-01' AND '2010-12-31'"}
{"question_id": 12, "sql": "SELECT MAX(f.`Free Meal Count (Ages 5-17)` * 1.0 / f.`Enrollment (Ages 5-17)`) AS max_ratio FROM satscores s JOIN frpm f ON s.cds = f.CDSCode WHERE s.NumTstTakr > 0 AND (s.NumGE1500 * 1.0 / s.NumTstTakr) > 0.3"}
{"question_id": 23, "sql": "SELECT sch.School, sch.Street FROM schools sch JOIN frpm f ON sch.CDSCode = f.CDSCode WHERE (f.`Enrollment (K-12)` - f.`Enrollment (Ages 5-17)`) > 30"}
{"question_id": 24, "sql": "SELECT f.`School Name` FROM frpm f JOIN satscores s ON f.CDSCode = s.cds WHERE (f.`Free Meal Count (K-12)` * 1.0 / f.`Enrollment (K-12)`) > 0.1 AND s.NumGE1500 > 0"}
{"question_id": 25, "sql": "SELECT s.sname, f.`Charter Funding Type` FROM satscores s JOIN schools sch ON s.cds = sch.CDSCode JOIN frpm f ON f.CDSCode = sch.CDSCode WHERE sch.District LIKE 'Riverside%' AND s.AvgScrMath > 400"}
{"question_id": 26, "sql": "SELECT f.`School Name`, sch.Street, sch.City, sch.State, sch.Zip FROM frpm f JOIN schools sch ON f.CDSCode = sch.CDSCode WHERE f.`County Name` = 'Monterey' AND f.`School Type` = 'High Schools (Public)' AND f.`FRPM Count (Ages 5-17)` > 800"}
{"question_id": 27, "sql": "SELECT sch.School, s.AvgScrWrite, sch.Phone FROM schools sch LEFT JOIN satscores s ON sch.CDSCode = s.cds WHERE (sch.OpenDate > '1991-12-31' OR sch.ClosedDate < '2000-01-01')"}
{"question_id": 31, "sql": "SELECT (f.`Free Meal Count (K-12)` * 1.0 / f.`Enrollment (K-12)`) AS ratio FROM frpm f ORDER BY f.`Enrollment (K-12)` DESC LIMIT 2 OFFSET 9"}
{"question_id": 5, "sql": "SELECT COUNT(*) FROM satscores s JOIN schools sch ON s.cds = sch.CDSCode WHERE s.AvgScrMath > 400 AND sch.Virtual = 'F'"}
{"question_id": 11, "sql": "SELECT CDSCode FROM frpm WHERE (`Enrollment (K-12)` + `Enrollment (Ages 5-17)`) > 500"}
{"question_id": 17, "sql": "SELECT sch.CharterNum, s.AvgScrWrite, RANK() OVER (ORDER BY s.AvgScrWrite DESC) AS WritingScoreRank FROM satscores s JOIN schools sch ON s.cds = sch.CDSCode WHERE s.AvgScrWrite > 499 AND sch.CharterNum IS NOT NULL"}
